contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We take callee and calldata; forward is non-payable so do not send Ether (amount parameter must be zero)
    function run(address callee, bytes calldata data, uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        // require that no Ether is forwarded to c through this invocation of run
        require(amount == 0);
        // ensure the test contract has at least 0 balance (trivial) but satisfies template guidance
        require(address(this).balance >= amount);

        uint256 beforeC = address(c).balance;
        uint256 beforeThis = address(this).balance;

        bool reverted;
        c.forward(callee, data); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // General rule: forward does not change balances of c or this contract (regardless of revert)
        assert(address(c).balance == beforeC && address(this).balance == beforeThis && (reverted || !reverted));
    }

    receive() external payable {}
}

